interface OscilarState {
  transactionID: string | null;
  tabID: string | null;
}

let oscilarState: OscilarState = {
  transactionID: null,
  tabID: null
};

export const setOscilarIDs = (transactionID: string, tabID: string) => {
  oscilarState = {
    transactionID,
    tabID
  };
};

export const getOscilarIDs = (): OscilarState => ({ ...oscilarState });
